// Family Planner NAB ingest. Mirrors app/n8n/bank-ingest.code-node.js
// (parseTransactionsCsv + ingestTransactionsDir, source 'NAB'). Runs off the
// always-present Schedule item and reads the mounted scrape folder itself via
// fs, so a quiet poll (no new files) cannot short-circuit the chain before the
// sentinel is emitted (the empty-items trap). Emits one item per parsed row, OR
// one { _sentinel:true } item when there are no rows, so the dual-filter +
// Heartbeat always fire. Account slug = the CSV basename (scraper writes
// <login>-<account>.csv, e.g. nab1-everyday.csv). KEEP IN SYNC with
// bank-ingest.code-node.js.
//
// MOUNT: assumes C:\BankScrapes\nab is bind-mounted to /data/bankscrapes/nab
// in the n8n container (the same mount as the other banks covers it). Confirm
// at deploy (see bank-ingest.BUILD-SHEET.md).
//
// CSV FORMAT (confirmed from a real export 2026-06-30): 10 columns —
// Date(0),Amount(1),Account Number(2),(3),Transaction Type(4),Transaction
// Details(5),Balance(6),Category(7),Merchant Name(8),Processed On(9). Date is
// `D MMM YY` (e.g. 30 Jun 26). Amount is col 1, details col 5, merchant col 8.
const fs = require('fs');
const path = require('path');
const ROOT = '/data/bankscrapes/nab';

function parseCsvLine(line) {
  const fields = []; let i = 0;
  while (i <= line.length) {
    if (line[i] === '"') {
      let end = i + 1; while (end < line.length && line[end] !== '"') end++;
      fields.push(line.slice(i + 1, end)); i = end + 1; if (line[i] === ',') i++;
    } else {
      let end = i; while (end < line.length && line[end] !== ',') end++;
      fields.push(line.slice(i, end)); i = end + 1;
    }
  }
  return fields.map(f => f.trim());
}
function parseNabDate(str) {
  const M = { Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11 };
  const p = String(str).trim().split(/\s+/);
  if (p.length !== 3) return null;
  const day = parseInt(p[0],10), month = M[p[1]], year = 2000 + parseInt(p[2],10);
  if (isNaN(day) || month === undefined || isNaN(year)) return null;
  return new Date(year, month, day);
}
function parseAmount(str) {
  if (str === undefined || str === null) return null;
  const c = String(str).replace(/[\s",]/g, ''); if (!c.length) return null;
  const n = parseFloat(c); return isNaN(n) ? null : n;
}
function toDateOnly(d) {
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
function txKey(tx) {
  return `${tx.dateStr}|${tx.amount}|${tx.details}|${tx.account}`.replace(/[.$#[\]/ -]/g, '_');
}
const KEEP_DAYS = 14; // each daily scrape covers ~38 days of history, so folders older than this add no new rows
const STALE_CUTOFF = new Date(Date.now() - KEEP_DAYS * 864e5);
const isStaleDir = nm => /^\d{4}-\d{2}-\d{2}$/.test(nm) && new Date(nm) < STALE_CUTOFF;
function listCsv(dir, acc) {
  let entries; try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) { return acc; }
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) { if (!isStaleDir(e.name)) listCsv(full, acc); }
    else if (/\.csv$/i.test(e.name)) acc.push(full);
  }
  return acc;
}

const out = [];
for (const file of listCsv(ROOT, [])) {
  let text; try { text = fs.readFileSync(file, 'utf8'); } catch (e) { continue; }
  const slug = path.basename(file).replace(/\.csv$/i, '') || 'nab-unknown';
  const lines = text.split(/\r?\n/);
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim(); if (!line) continue;
    const cols = parseCsvLine(line); if (cols.length < 9) continue;
    const date = parseNabDate(cols[0]); if (!date) continue;
    const amount = parseAmount(cols[1]); if (amount === null) continue;
    const details = cols[5] || '';
    const merchant = cols[8] ? cols[8] : details.substring(0,30).trim();
    const row = { date: toDateOnly(date), dateStr: cols[0].trim(), amount: Math.abs(amount), isRefund: amount > 0, account: slug, source: 'NAB', txType: '', details, category: '', merchant, glLine: '', isDuplicate: false };
    out.push({ json: { _sentinel: false, _key: txKey(row), row } });
  }
}
if (out.length === 0) return [{ json: { _sentinel: true } }];
return out;
